"""
Long Hair Identification System - Built-in Photo Demo
======================================================

Run:
    python long_hair_photo_demo.py

Contains embedded illustrative portraits and eight predefined test cases.
No external dataset, network download, model weights, or training is required.

IMPORTANT:
This is a GUI/rule demonstration, not a trained image-recognition model.
The portrait images are illustrative; age, real-gender input, and hair-length
labels are preset test values. For custom photos, enter the age/gender/hair
length inputs yourself; the program does not infer them from pixels.
"""

import base64
import csv
import io
import os
import tkinter as tk
from tkinter import ttk, filedialog, messagebox

try:
    from PIL import Image, ImageTk, ImageOps
except ImportError:
    Image = ImageTk = ImageOps = None

# These JPEG portraits are embedded in this Python file.
# They are loaded from memory; no external image files are needed.
BUILTIN_PHOTOS_B64 = {
    "case_1": "",
    "case_2": "",
    "case_3": "",
    "case_4": "",
    "case_5": "",
    "case_6": "",
    "case_7": "",
    "case_8": "",
    "preview_case_1": "",
}

# Case ID, age, supplied real-gender result, hair length, photo key, example
BUILT_IN_CASES = [
    ("CASE-01", 24, "Male",   "Long",  "case_1"),
    ("CASE-02", 27, "Female", "Short", "case_2"),
    ("CASE-03", 19, "Female", "Long",  "case_3"),
    ("CASE-04", 35, "Male",   "Long",  "case_4"),
    ("CASE-05", 20, "Male",   "Short", "case_5"),
    ("CASE-06", 30, "Female", "Long",  "case_6"),
    ("CASE-07", 42, "Female", "Short", "case_7"),
    ("CASE-08", 16, "Male",   "Long",  "case_8"),
]


def apply_rule(age, real_gender, hair_length):
    """Apply the assignment's age 20-30 inclusive decision rule."""
    age = int(age)
    if age < 0:
        raise ValueError("Age must be zero or greater.")
    if real_gender not in ("Male", "Female"):
        raise ValueError("Real gender must be Male or Female.")
    if hair_length not in ("Long", "Short"):
        raise ValueError("Hair length must be Long or Short.")

    if 20 <= age <= 30:
        final_gender = "Female" if hair_length == "Long" else "Male"
        return final_gender, "Hair length override (age 20-30)"
    return real_gender, "Real-gender result (outside age range)"


class LongHairPhotoDemo:
    def __init__(self, root):
        if Image is None:
            messagebox.showerror(
                "Pillow is required",
                "Install Pillow in your active venv using:\n"
                "python -m pip install pillow"
            )
            root.destroy()
            return

        self.root = root
        self.root.title("Long Hair Identification System")
        self.root.geometry("1220x790")
        self.root.minsize(980, 650)

        self.rows = []
        self.photo_refs = {}
        self.large_photo_ref = None
        self.custom_image = None
        self.custom_image_name = "Built-in sample portrait"

        self._load_embedded_photos()
        self._configure_style()
        self._build_header()
        self._build_summary()
        self._build_main_area()
        self._build_custom_inputs()
        self._build_footer()
        self.run_all_cases()

    def _load_embedded_photos(self):
        for key, payload in BUILTIN_PHOTOS_B64.items():
            raw = base64.b64decode(payload, validate=True)
            image = Image.open(io.BytesIO(raw)).convert("RGB")
            self.photo_refs[key] = image

    def _configure_style(self):
        self.root.configure(bg="#edf3f8")
        style = ttk.Style()
        try:
            style.theme_use("clam")
        except tk.TclError:
            pass
        style.configure("Treeview", rowheight=62, font=("Segoe UI", 10))
        style.configure(
            "Treeview.Heading",
            font=("Segoe UI", 10, "bold"),
            background="#dce8f2",
            foreground="#183a57",
        )
        style.configure("TButton", font=("Segoe UI", 10), padding=7)
        style.configure("TCombobox", padding=4)

    def _build_header(self):
        header = tk.Frame(self.root, bg="#123f63", padx=20, pady=14)
        header.pack(fill="x")
        tk.Label(
            header, text="LONG HAIR IDENTIFICATION SYSTEM",
            bg="#123f63", fg="white", font=("Segoe UI", 20, "bold")
        ).pack(anchor="w")
        tk.Label(
            header,
            text="Age 20-30: hair length decides gender  |  Outside this range: keep real-gender result",
            bg="#123f63", fg="#e6f0f8", font=("Segoe UI", 10)
        ).pack(anchor="w", pady=(3, 0))

    def _build_summary(self):
        frame = tk.Frame(self.root, bg="#edf3f8", padx=12, pady=10)
        frame.pack(fill="x")
        self.stat_vars = [tk.StringVar(value="0") for _ in range(4)]
        labels = ["Total Cases", "Age 20-30", "Outside Range", "Evaluated"]
        for label, var in zip(labels, self.stat_vars):
            card = tk.Frame(frame, bg="white", bd=1, relief="solid", padx=14, pady=8)
            card.pack(side="left", fill="x", expand=True, padx=5)
            tk.Label(card, text=label, bg="white", fg="#29465e",
                     font=("Segoe UI", 10, "bold")).pack(anchor="w")
            tk.Label(card, textvariable=var, bg="white", fg="#124b73",
                     font=("Segoe UI", 20, "bold")).pack(anchor="w")

    def _build_main_area(self):
        body = tk.Frame(self.root, bg="#edf3f8", padx=12, pady=2)
        body.pack(fill="both", expand=True)

        left = tk.Frame(body, bg="white", bd=1, relief="solid", padx=9, pady=9)
        left.pack(side="left", fill="y", padx=(0, 10))

        tk.Label(left, text="Selected Person", bg="#124b73", fg="white",
                 font=("Segoe UI", 11, "bold"), padx=10, pady=8).pack(fill="x")

        self.preview_label = tk.Label(left, bg="#e7eef5", text="Select a case",
                                      width=35, height=13)
        self.preview_label.pack(padx=5, pady=9)

        detail_box = tk.LabelFrame(left, text="Prediction Details",
                                   bg="white", fg="#173b57",
                                   font=("Segoe UI", 10, "bold"), padx=9, pady=8)
        detail_box.pack(fill="x", pady=(2, 0))
        self.detail_var = tk.StringVar(value="Select a row to view details.")
        tk.Label(detail_box, textvariable=self.detail_var, bg="white",
                 fg="#183a57", font=("Segoe UI", 10), justify="left",
                 wraplength=270).pack(anchor="w")

        right = tk.Frame(body, bg="white", bd=1, relief="solid", padx=7, pady=7)
        right.pack(side="left", fill="both", expand=True)

        tk.Label(right, text="Built-in Test Results (with Photos)",
                 bg="#124b73", fg="white", font=("Segoe UI", 12, "bold"),
                 padx=12, pady=8).pack(fill="x")

        table_frame = tk.Frame(right, bg="white")
        table_frame.pack(fill="both", expand=True, pady=(7, 0))

        columns = ("Case ID", "Age", "Real Gender", "Hair Length",
                   "Applied Rule", "Final Gender")
        self.table = ttk.Treeview(table_frame, columns=columns,
                                  show="tree headings", height=8)
        self.table.heading("#0", text="Person Image")
        self.table.column("#0", width=125, minwidth=110, anchor="center")
        widths = (90, 55, 105, 95, 220, 105)
        for col, width in zip(columns, widths):
            self.table.heading(col, text=col)
            self.table.column(col, width=width, minwidth=55, anchor="center")
        self.table.tag_configure("override", foreground="#075ba8")
        self.table.tag_configure("outside", foreground="#18723b")
        self.table.pack(side="left", fill="both", expand=True)

        scroll = ttk.Scrollbar(table_frame, orient="vertical",
                               command=self.table.yview)
        self.table.configure(yscrollcommand=scroll.set)
        scroll.pack(side="right", fill="y")
        self.table.bind("<<TreeviewSelect>>", self._on_select)

        self.rule_note = tk.Label(
            right,
            text="Rule: Age 20-30 inclusive → Long hair = Female; Short hair = Male. "
                 "Outside age 20-30 → use supplied real-gender result.",
            bg="#eaf2fa", fg="#25445d", anchor="w",
            justify="left", padx=10, pady=9, wraplength=820
        )
        self.rule_note.pack(fill="x", pady=(8, 0))

    def _build_custom_inputs(self):
        panel = tk.LabelFrame(
            self.root, text="Enter Your Own Test Input",
            bg="#edf3f8", fg="#173b57", font=("Segoe UI", 10, "bold"),
            padx=10, pady=8
        )
        panel.pack(fill="x", padx=18, pady=(8, 4))

        tk.Label(panel, text="Age:", bg="#edf3f8").grid(row=0, column=0, padx=5, pady=4)
        self.age_var = tk.StringVar(value="25")
        tk.Spinbox(panel, from_=0, to=120, width=7,
                   textvariable=self.age_var).grid(row=0, column=1, padx=5)

        tk.Label(panel, text="Real Gender:", bg="#edf3f8").grid(row=0, column=2, padx=5)
        self.gender_var = tk.StringVar(value="Male")
        ttk.Combobox(panel, textvariable=self.gender_var,
                     values=("Male", "Female"), state="readonly",
                     width=11).grid(row=0, column=3, padx=5)

        tk.Label(panel, text="Hair Length:", bg="#edf3f8").grid(row=0, column=4, padx=5)
        self.hair_var = tk.StringVar(value="Long")
        ttk.Combobox(panel, textvariable=self.hair_var,
                     values=("Short", "Long"), state="readonly",
                     width=11).grid(row=0, column=5, padx=5)

        ttk.Button(panel, text="Choose Image (optional)",
                   command=self.choose_custom_image).grid(row=0, column=6, padx=7)
        ttk.Button(panel, text="Predict / Add Case",
                   command=self.predict_custom).grid(row=0, column=7, padx=7)

        self.custom_image_status = tk.StringVar(value="No custom image selected")
        tk.Label(panel, textvariable=self.custom_image_status,
                 bg="#edf3f8", fg="#5c7184").grid(
                     row=1, column=0, columnspan=8, sticky="w", padx=5, pady=(4, 0)
                 )

    def _build_footer(self):
        footer = tk.Frame(self.root, bg="#edf3f8", padx=18, pady=10)
        footer.pack(fill="x")
        ttk.Button(footer, text="Run All Built-in Inputs",
                   command=self.run_all_cases).pack(side="left", padx=(0, 8))
        ttk.Button(footer, text="Export CSV",
                   command=self.export_csv).pack(side="left", padx=8)
        ttk.Button(footer, text="Clear Results",
                   command=self.clear_results).pack(side="left", padx=8)

        tk.Label(
            footer,
            text="Illustrative portraits + preset inputs: this demo does not infer age or hair from pixels.",
            bg="#edf3f8", fg="#667788", font=("Segoe UI", 9)
        ).pack(side="right")

    def _make_photo(self, image, size):
        fitted = ImageOps.contain(image, size, method=Image.Resampling.LANCZOS)
        canvas = Image.new("RGB", size, "#eaf1f7")
        x = (size[0] - fitted.width) // 2
        y = (size[1] - fitted.height) // 2
        canvas.paste(fitted, (x, y))
        return ImageTk.PhotoImage(canvas)

    def _photo_for_row(self, row):
        if row.get("custom_image") is not None:
            return self._make_photo(row["custom_image"], (118, 58))
        return self._make_photo(self.photo_refs[row["photo_key"]], (118, 58))

    def _set_preview(self, row):
        image = row.get("custom_image")
        if image is None:
            image = self.photo_refs[row["photo_key"]]
        self.large_photo_ref = self._make_photo(image, (300, 245))
        self.preview_label.configure(image=self.large_photo_ref, text="")
        self.preview_label.image = self.large_photo_ref

        self.detail_var.set(
            f"Case: {row['case_id']}\n"
            f"Age: {row['age']}\n"
            f"Real gender input: {row['real_gender']}\n"
            f"Hair length input: {row['hair_length']}\n"
            f"Applied rule: {row['rule']}\n"
            f"Final gender: {row['final_gender']}"
        )

    def _insert_row(self, row):
        row["tree_image"] = self._photo_for_row(row)
        tag = "override" if 20 <= row["age"] <= 30 else "outside"
        self.table.insert(
            "", "end", iid=row["case_id"], image=row["tree_image"], text="",
            values=(row["case_id"], row["age"], row["real_gender"],
                    row["hair_length"], row["rule"], row["final_gender"]),
            tags=(tag,)
        )
        self.rows.append(row)

    def run_all_cases(self):
        self.clear_results()
        for case_id, age, gender, hair, photo_key in BUILT_IN_CASES:
            final_gender, rule = apply_rule(age, gender, hair)
            row = {
                "case_id": case_id,
                "age": age,
                "real_gender": gender,
                "hair_length": hair,
                "rule": rule,
                "final_gender": final_gender,
                "photo_key": photo_key,
                "custom_image": None,
            }
            self._insert_row(row)

        total = len(self.rows)
        in_range = sum(20 <= row["age"] <= 30 for row in self.rows)
        self.stat_vars[0].set(str(total))
        self.stat_vars[1].set(str(in_range))
        self.stat_vars[2].set(str(total - in_range))
        self.stat_vars[3].set(str(total))
        first_id = self.rows[0]["case_id"]
        self.table.selection_set(first_id)
        self.table.focus(first_id)
        self._set_preview(self.rows[0])

    def _on_select(self, _event=None):
        selected = self.table.selection()
        if not selected:
            return
        row = next((r for r in self.rows if r["case_id"] == selected[0]), None)
        if row:
            self._set_preview(row)

    def choose_custom_image(self):
        path = filedialog.askopenfilename(
            title="Choose a sample image",
            filetypes=[("Image files", "*.jpg *.jpeg *.png *.bmp")]
        )
        if not path:
            return
        try:
            image = Image.open(path).convert("RGB")
            image.thumbnail((360, 330), Image.Resampling.LANCZOS)
            self.custom_image = image.copy()
            self.custom_image_name = os.path.basename(path)
            self.custom_image_status.set(f"Selected image: {self.custom_image_name}")
            self.large_photo_ref = self._make_photo(image, (300, 245))
            self.preview_label.configure(image=self.large_photo_ref, text="")
            self.preview_label.image = self.large_photo_ref
        except Exception as exc:
            messagebox.showerror("Image error", f"Could not open image:\n{exc}")

    def predict_custom(self):
        try:
            age = int(self.age_var.get().strip())
            gender = self.gender_var.get()
            hair = self.hair_var.get()
            final_gender, rule = apply_rule(age, gender, hair)
        except (ValueError, TypeError) as exc:
            messagebox.showerror("Invalid input", str(exc))
            return

        case_id = f"CUSTOM-{len([r for r in self.rows if r['case_id'].startswith('CUSTOM-')]) + 1:02d}"
        # If no image is selected, choose a built-in portrait with a matching
        # hairstyle for the visual demonstration.
        if self.custom_image is not None:
            custom_image = self.custom_image.copy()
            photo_key = None
        else:
            custom_image = None
            if hair == "Long" and gender == "Male":
                photo_key = "case_1"
            elif hair == "Short" and gender == "Female":
                photo_key = "case_2"
            elif hair == "Long" and gender == "Female":
                photo_key = "case_3"
            else:
                photo_key = "case_5"

        row = {
            "case_id": case_id, "age": age,
            "real_gender": gender, "hair_length": hair,
            "rule": rule, "final_gender": final_gender,
            "photo_key": photo_key, "custom_image": custom_image,
        }
        self._insert_row(row)
        self.stat_vars[0].set(str(len(self.rows)))
        self.stat_vars[1].set(str(sum(20 <= r["age"] <= 30 for r in self.rows)))
        self.stat_vars[2].set(str(sum(not (20 <= r["age"] <= 30) for r in self.rows)))
        self.stat_vars[3].set(str(len(self.rows)))
        self.table.selection_set(case_id)
        self.table.focus(case_id)
        self._set_preview(row)
        messagebox.showinfo(
            "Demo result",
            f"Age: {age}\nReal gender input: {gender}\nHair length input: {hair}\n"
            f"Applied rule: {rule}\n\nFinal displayed gender: {final_gender}\n\n"
            "This is a rule-based demo result, not a prediction from the photo."
        )
        self.custom_image = None
        self.custom_image_status.set("No custom image selected")

    def clear_results(self):
        for item in self.table.get_children():
            self.table.delete(item)
        self.rows = []
        for variable in self.stat_vars:
            variable.set("0")
        self.preview_label.configure(image="", text="Select a case")
        self.preview_label.image = None
        self.large_photo_ref = None
        self.detail_var.set("Results cleared.")

    def export_csv(self):
        if not self.rows:
            messagebox.showinfo("No results", "Run the built-in cases first.")
            return
        path = filedialog.asksaveasfilename(
            title="Export test results", defaultextension=".csv",
            initialfile="long_hair_photo_demo_results.csv",
            filetypes=[("CSV files", "*.csv")]
        )
        if not path:
            return
        fields = ["case_id", "age", "real_gender", "hair_length", "rule", "final_gender"]
        with open(path, "w", newline="", encoding="utf-8") as file:
            writer = csv.DictWriter(file, fieldnames=fields)
            writer.writeheader()
            for row in self.rows:
                writer.writerow({field: row[field] for field in fields})
        messagebox.showinfo("Export complete", f"Saved {len(self.rows)} cases to:\n{path}")


if __name__ == "__main__":
    root = tk.Tk()
    app = LongHairPhotoDemo(root)
    root.mainloop()
